const items = $input.all();

function toText(value) {
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) return value.length ? toText(value[0]) : '';
  return String(value).trim();
}

function formatNumeroRingover(value) {
  const raw = toText(value);
  if (!raw) return '';

  let cleaned = raw.replace(/\s+/g, '').replace(/[().-]/g, '');

  if (cleaned.startsWith('00')) cleaned = `+${cleaned.slice(2)}`;
  if (cleaned.startsWith('+')) return `+${cleaned.slice(1).replace(/\D/g, '')}`;

  const digits = cleaned.replace(/\D/g, '');

  if (digits.startsWith('0') && digits.length === 10) {
    return `+33${digits.slice(1)}`;
  }

  if (digits.length === 9 && /^[1-9]/.test(digits)) {
    return `+33${digits}`;
  }

  if (digits.startsWith('33')) {
    return `+${digits}`;
  }

  return digits ? `+${digits}` : '';
}

function formatDateFr(date) {
  return new Intl.DateTimeFormat('fr-FR', {
    timeZone: 'Europe/Paris',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  }).format(date);
}

function formatHeureFr(date) {
  return new Intl.DateTimeFormat('fr-FR', {
    timeZone: 'Europe/Paris',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(date);
}

return items.map(item => {
  const data = item.json.fields || item.json;

  const prenom = toText(data['Prénom']);
  const numeroRingover = formatNumeroRingover(data['Numéro']);

  const rawDate = toText(data['Date de certification']);
  const dateCertification = new Date(rawDate);

  if (isNaN(dateCertification.getTime())) {
    return {
      json: {
        ...item.json,
        prenom_apprenant: prenom,
        numero_ringover: numeroRingover,
        erreur_date_certification: `Date invalide : ${rawDate}`,
      },
    };
  }

  const waitDate = new Date(dateCertification.getTime() - 60 * 60 * 1000);

  return {
    json: {
      ...item.json,

      prenom_apprenant: prenom,
      numero_ringover: numeroRingover,

      date_certification_fr: formatDateFr(dateCertification),
      heure_certification_fr: formatHeureFr(dateCertification),
      date_heure_certification_fr: `${formatDateFr(dateCertification)} à ${formatHeureFr(dateCertification)}`,

      wait_jusqua_iso_utc: waitDate.toISOString(),
      wait_jusqua_fr: `${formatDateFr(waitDate)} à ${formatHeureFr(waitDate)}`,

      erreur_date_certification: '',
    },
  };
});
